import{_ as a,o as n,c as i,a2 as t}from"./chunks/framework.mRCPFc5l.js";const s="/assets/quality-summary.CFjFpV1y.png",o="/assets/spellchecker.BLy7-TJM.png",r="/assets/dictionary-manager.BRZLa3oK.png",f=JSON.parse('{"title":"Quality Checks","description":"","frontmatter":{},"headers":[],"relativePath":"en_US/05-quality-checks.md","filePath":"en_US/05-quality-checks.md"}'),l={name:"en_US/05-quality-checks.md"};function d(c,e,h,g,p,u){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="quality-checks" tabindex="-1">Quality Checks <a class="header-anchor" href="#quality-checks" aria-label="Permalink to &quot;Quality Checks&quot;">​</a></h1><p>Find and resolve reading-speed, line-length, timing, completeness, and spelling problems.</p><h2 id="what-you-can-do-on-this-page" tabindex="-1">What you can do on this page <a class="header-anchor" href="#what-you-can-do-on-this-page" aria-label="Permalink to &quot;What you can do on this page&quot;">​</a></h2><ul><li>Apply project thresholds for long lines and high CPS.</li><li>Navigate missing episodes/translations, invalid ranges, and overlaps.</li><li>Check translation spelling with a local dictionary.</li><li>Manage ignored words and a per-dictionary user dictionary.</li></ul><h2 id="set-quality-thresholds" tabindex="-1">Set quality thresholds <a class="header-anchor" href="#set-quality-thresholds" aria-label="Permalink to &quot;Set quality thresholds&quot;">​</a></h2><p>In <strong>Project Setup → Other Parameters</strong>, set <strong>Maximum CPS</strong>, <strong>Line Length</strong>, and <strong>Spellcheck Language</strong>. These values drive warnings and tools; they never rewrite subtitle content automatically.</p><h2 id="find-long-subtitles" tabindex="-1">Find long subtitles <a class="header-anchor" href="#find-long-subtitles" aria-label="Permalink to &quot;Find long subtitles&quot;">​</a></h2><p>Click the <strong>Filter Long</strong> counter to show translations over the configured line length. Shorten the translation, use <strong>Break Selected</strong>, or split the row where meaning and timing permit. Character count excludes subtitle line-break markers but preserves spaces.</p><h2 id="find-high-reading-speed" tabindex="-1">Find high reading speed <a class="header-anchor" href="#find-high-reading-speed" aria-label="Permalink to &quot;Find high reading speed&quot;">​</a></h2><p>Click <strong>Filter CPS</strong> to show subtitles whose translation character count is too high for their duration. Shorten the translation, safely extend timing, or split an overloaded subtitle. CPS recalculates after text or timing edits.</p><h2 id="check-timing-and-completeness" tabindex="-1">Check timing and completeness <a class="header-anchor" href="#check-timing-and-completeness" aria-label="Permalink to &quot;Check timing and completeness&quot;">​</a></h2><p>The validation summary reports invalid ranges, missing episodes, missing translations, and overlapping timings.</p><p><img src="'+s+'" alt="Validation summary with timing, translation, overlap, and spelling counts"></p><p>Click a counter to jump to the next matching row. The counter navigates rather than filtering. Timing warnings are not automatic fixes; verify changes against video.</p><h2 id="enable-spellcheck" tabindex="-1">Enable spellcheck <a class="header-anchor" href="#enable-spellcheck" aria-label="Permalink to &quot;Enable spellcheck&quot;">​</a></h2><ol><li>Open <strong>Settings</strong>.</li><li>Enable <strong>Spellcheck translation</strong>.</li><li>Open <strong>Dictionaries</strong> and choose an installed dictionary.</li><li>Wait for the background scan to finish.</li></ol><p>Spellcheck scans the <code>translation</code> field only. Large workspaces are processed incrementally so editing can continue. The Spellchecker is unavailable when no dictionary is installed.</p><h2 id="review-spelling-suggestions" tabindex="-1">Review spelling suggestions <a class="header-anchor" href="#review-spelling-suggestions" aria-label="Permalink to &quot;Review spelling suggestions&quot;">​</a></h2><p>Press <code>F7</code> or click <strong>Spellchecker</strong>.</p><p><img src="'+o+`" alt="Spellchecker with the current word, suggestions, and actions"></p><p>Use <strong>Previous</strong> and <strong>Next</strong>, select a suggestion, then apply it. Direct edits in the grid also update results while preserving focus where possible.</p><h2 id="ignore-spelling-alerts" tabindex="-1">Ignore spelling alerts <a class="header-anchor" href="#ignore-spelling-alerts" aria-label="Permalink to &quot;Ignore spelling alerts&quot;">​</a></h2><ul><li><strong>Ignore Once</strong> removes only the current occurrence.</li><li><strong>Ignore All</strong> ignores that word throughout the current workspace.</li><li><strong>Add to Dictionary</strong> adds a correct name or specialist term to the active dictionary&#39;s user dictionary.</li></ul><p>These actions update spelling statistics without changing the active row filter.</p><h2 id="install-and-switch-spelling-dictionaries" tabindex="-1">Install and switch spelling dictionaries <a class="header-anchor" href="#install-and-switch-spelling-dictionaries" aria-label="Permalink to &quot;Install and switch spelling dictionaries&quot;">​</a></h2><p>GridSubStudio reads Hunspell-format dictionaries but does not bundle, download, or recommend a particular dictionary. Obtain one from a trusted source and check its license.</p><h3 id="understand-the-hunspell-files" tabindex="-1">Understand the Hunspell files <a class="header-anchor" href="#understand-the-hunspell-files" aria-label="Permalink to &quot;Understand the Hunspell files&quot;">​</a></h3><p>A dictionary requires a matching pair:</p><ul><li><code>.dic</code> contains words and optional rule flags. Its first line is commonly a word count.</li><li><code>.aff</code> declares encoding, prefixes/suffixes, replacements, and suggestion rules.</li></ul><p>Both files must come from the same dictionary package. Downloads often contain names such as <code>en_US.aff</code> and <code>en_US.dic</code>; inside GridSubStudio&#39;s dictionary folder, rename the pair to <code>index.aff</code> and <code>index.dic</code>. Do not mix languages or resave the files with a text editor unless you understand the format and encoding.</p><h3 id="install-the-files" tabindex="-1">Install the files <a class="header-anchor" href="#install-the-files" aria-label="Permalink to &quot;Install the files&quot;">​</a></h3><ol><li>Open <strong>Settings → Dictionaries → Open Folder</strong>.</li><li>Fully extract downloaded archives.</li><li>Create one direct subfolder per dictionary, such as <code>en_US</code> or <code>de_DE</code>.</li><li>Place the matching files inside as <code>index.aff</code> and <code>index.dic</code>.</li><li>Optionally keep <code>LICENSE</code>, <code>COPYING</code>, or <code>README</code> beside them.</li><li>Return to GridSubStudio and click <strong>Refresh</strong>.</li><li>Click the dictionary name to mark it <strong>Active</strong>.</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dictionary folder/</span></span>
<span class="line"><span>  en_US/</span></span>
<span class="line"><span>    index.aff</span></span>
<span class="line"><span>    index.dic</span></span>
<span class="line"><span>    LICENSE          (optional)</span></span>
<span class="line"><span>  de_DE/</span></span>
<span class="line"><span>    index.aff</span></span>
<span class="line"><span>    index.dic</span></span></code></pre></div><p>Loose files at the root, archives, nested extra folders, or files left as <code>en_US.aff</code>/<code>en_US.dic</code> are not detected.</p><h3 id="switch-and-verify-a-dictionary" tabindex="-1">Switch and verify a dictionary <a class="header-anchor" href="#switch-and-verify-a-dictionary" aria-label="Permalink to &quot;Switch and verify a dictionary&quot;">​</a></h3><p>Only direct subfolders containing both required filenames appear in the installed list.</p><p><img src="`+r+'" alt="Dictionary Manager with the install folder and active dictionary"></p><p>Close Dictionary Manager to trigger a full recheck. Test with a known misspelling. GridSubStudio uses a local Hunspell-compatible engine; complex morphology or suggestions may differ from LibreOffice, Firefox, Hunspell, or Nuspell. It does not map a short ID such as <code>en</code> to a regional dictionary or fall back silently when the selected dictionary disappears.</p><h2 id="manage-ignored-words-and-user-words" tabindex="-1">Manage ignored words and user words <a class="header-anchor" href="#manage-ignored-words-and-user-words" aria-label="Permalink to &quot;Manage ignored words and user words&quot;">​</a></h2><p><strong>Ignore Words</strong> belongs to the current CSV/project workspace. <strong>User Dictionary</strong> belongs to the active dictionary and is shared across projects. Changes made in nested managers are applied when the outer Dictionary Manager closes, triggering one consolidated recheck.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>Dictionary not listed:</strong> extract it into a direct subfolder with exact <code>index.aff</code> and <code>index.dic</code> names.</li><li><strong>Dictionary fails to load:</strong> restore both files from the same original package and preserve their encoding.</li><li><strong>Results did not update:</strong> close nested word managers, then close Dictionary Manager.</li><li><strong>No suggestion:</strong> edit manually, ignore once, or add a verified word to the user dictionary.</li><li><strong>Results differ from another app:</strong> verify dictionary version and region, then test representative subtitle text.</li></ul>',42)])])}const y=a(l,[["render",d]]);export{f as __pageData,y as default};
